/// Keeps empties rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryEmptyRepository {
    rows: Arc<Mutex<Vec<Empty>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryEmptyRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Empty> {
        let mut rows: Vec<Empty> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Empty) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Empty) -> (Option<i64>,) {
    (row.id,)
}

#[async_trait]
impl EmptyRepository for MemoryEmptyRepository {
    async fn find_by_id(&self, id: i64) -> Result<Option<Empty>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Empty>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn insert(&self, entity: Empty) -> Result<Empty, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Empty) -> Result<Empty, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Empty) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

