//! The service of the "empties" table.

use crate::common::Page;
use crate::dtos::empty::{EmptyCreate, EmptyRead, EmptyUpdate};
use crate::entities::empty::Empty;
use crate::errors::DomainError;
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// Operations on empties. Each write runs in a transaction of its own.
pub struct EmptyService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl EmptyService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Empty after checking it.
    pub async fn create_empty(&self, data: EmptyCreate) -> Result<EmptyRead, DomainError> {
        let values = Values { note: data.note.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Empty::default();
        apply_values(&mut entity, &values);
