    class: Option<Option<String>>,
    metadata: Option<Option<String>>,
    date: Option<Option<chrono::NaiveDate>>,
    time: Option<Option<chrono::NaiveTime>>,
    text: Option<Option<String>>,
    list: Option<Option<String>>,
    str: Option<Option<String>>,
    int: Option<Option<i32>>,
    due_date: Option<Option<chrono::NaiveDate>>,
    closes_at: Option<Option<chrono::NaiveTime>>,
    kind_code: Option<Option<String>>,
    kind_day: Option<Option<chrono::NaiveDate>>,
    thing_id: Option<Option<uuid::Uuid>>,
    parent_id: Option<Option<i64>>,
}

/// Checks the values against the rules of the "Order" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.user.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.user.is_some() {
                errors.push(FieldError::new("user", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 40 {
                errors.push(FieldError::new("user", "is longer than 40 characters"));
            }
        }
    }
    match values.group.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if !creating && values.group.is_some() {
                errors.push(FieldError::new("group", "cannot be empty"));
            }
        }
        Some(value) => {
            if !((*value as f64) >= 0.0) {
                errors.push(FieldError::new("group", "must be >= 0"));
            }
        }
    }
    match values.customer_name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.customer_name.is_some() {
                errors.push(FieldError::new("customerName", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 60 {
                errors.push(FieldError::new("customerName", "is longer than 60 characters"));
            }
        }
    }
    if let Some(value) = values.text.as_ref().and_then(|value| value.as_ref()) {
        if value.chars().count() > 20 {
            errors.push(FieldError::new("text", "is longer than 20 characters"));
        }
    }
    if let Some(value) = values.str.as_ref().and_then(|value| value.as_ref()) {
        if value.chars().count() > 10 {
            errors.push(FieldError::new("str", "is longer than 10 characters"));
        }
    }
    match values.due_date.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.due_date.is_some() {
                errors.push(FieldError::new("dueDate", "is required"));
            }
        }
        Some(_) => {}
    }
    if let Some(value) = values.kind_code.as_ref().and_then(|value| value.as_ref()) {
        if value.chars().count() > 10 {
            errors.push(FieldError::new("kind_code", "is longer than 10 characters"));
        }
    }
    {
        let thing_id = values.thing_id.clone().unwrap_or_else(|| current.and_then(|current| current.thing_id));
        if let Some(thing_id) = thing_id {
            if uow.things().find_by_id(thing_id).await?.is_none() {
                errors.push(FieldError::new("thing_id", "no Thing has this key"));
            }
        }
    }
    {
        let parent_id = values.parent_id.clone().unwrap_or_else(|| current.and_then(|current| current.parent_id));
        if let Some(parent_id) = parent_id {
            if uow.order().find_by_id(parent_id).await?.is_none() {
                errors.push(FieldError::new("parentId", "no Order has this key"));
            }
        }
    }
    {
        let kind_code = values.kind_code.clone().unwrap_or_else(|| current.and_then(|current| current.kind_code.clone()));
        let kind_day = values.kind_day.clone().unwrap_or_else(|| current.and_then(|current| current.kind_day));
        if let (Some(kind_code), Some(kind_day)) = (kind_code, kind_day) {
            if uow.kinds().find_by_code_and_day(kind_code, kind_day).await?.is_none() {
                errors.push(FieldError::new("kind_code, kind_day", "no Kind has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Order".to_string(), errors })
    }
}

/// Values that must be unique are not taken by another row.
async fn check_unique(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    {
        let customer_name = values.customer_name.clone().unwrap_or_else(|| current.and_then(|current| current.customer_name.clone()));
        if let Some(customer_name) = customer_name {
            if let Some(other) = uow.order().find_by_customer_name(customer_name).await? {
                if current.is_none_or(|current| other.id != current.id) {
                    return Err(DomainError::conflict("Order", "customerName is already taken", &["customer_name"]));
                }
            }
        }
    }
    Ok(())
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Order>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    check_unique(uow, values, current).await
}

