/// Operations on things. Each write runs in a transaction of its own.
pub struct ThingService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl ThingService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Thing after checking it.
    pub async fn create_thing(&self, data: ThingCreate) -> Result<ThingRead, DomainError> {
        let values = Values { token: data.token.map(Some), small: data.small.map(Some), num: data.num.map(Some), big: data.big.map(Some), price: data.price.map(Some), r: data.r.map(Some), d: data.d.map(Some), flag: data.flag.map(Some), born: data.born.map(Some), opens: data.opens.map(Some), opens_tz: data.opens_tz.map(Some), at: data.at.map(Some), at_tz: data.at_tz.map(Some), bin: data.bin.map(Some), data: data.data.map(Some), plain: data.plain.map(Some), feeling: data.feeling.map(Some), tags: data.tags.map(Some), numbers: data.numbers.map(Some), ip: data.ip.map(Some), span: data.span.map(Some), code: data.code.map(Some), note: data.note.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Thing::default();
        apply_values(&mut entity, &values);
        let created = uow.things().insert(entity).await?;
        transaction.commit().await?;
        Ok(read(created))
    }

    /// The Thing with this key; NotFound when there is none.
    pub async fn get_thing(&self, id: uuid::Uuid) -> Result<ThingRead, DomainError> {
        find(self.unit_of_work.as_ref(), id).await.map(read)
    }

    /// A page of things, by primary key.
    pub async fn list_things(&self, offset: u64, limit: u64) -> Result<Page<ThingRead>, DomainError> {
        self.unit_of_work.things().list(offset, limit).await.map(|page| page.map(read))
    }

    /// Changes the given values of a Thing.
    pub async fn update_thing(&self, id: uuid::Uuid, changes: ThingUpdate) -> Result<ThingRead, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        let updated = uow.things().update(current).await?;
        transaction.commit().await?;
        Ok(read(updated))
    }

    /// Deletes a Thing.
    pub async fn delete_thing(&self, id: uuid::Uuid) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let current = find(uow, id).await?;
        uow.things().delete(&current).await?;
        transaction.commit().await?;
        Ok(())
    }
}

