//! The unit of work: the repositories of every table, and the transactions that group their writes.

use async_trait::async_trait;
use crate::database::Db;
use crate::errors::DomainError;
use crate::repositories::empty::{EmptyRepository, MemoryEmptyRepository, SqlEmptyRepository};
use crate::repositories::entry::{EntryRepository, MemoryEntryRepository, SqlEntryRepository};
use crate::repositories::kind::{KindRepository, MemoryKindRepository, SqlKindRepository};
use crate::repositories::order::{MemoryOrderRepository, OrderRepository, SqlOrderRepository};
use crate::repositories::thing::{MemoryThingRepository, SqlThingRepository, ThingRepository};
use sea_orm::{DatabaseConnection, DatabaseTransaction, TransactionTrait};

/// What services depend on: a repository per table and transactions. Each service operation runs in a transaction of its own: begin() opens it, commit() keeps its changes.
#[async_trait]
pub trait UnitOfWork: Send + Sync {
    fn things(&self) -> Box<dyn ThingRepository + '_>;
    fn kinds(&self) -> Box<dyn KindRepository + '_>;
    fn order(&self) -> Box<dyn OrderRepository + '_>;
    fn entries(&self) -> Box<dyn EntryRepository + '_>;
    fn empties(&self) -> Box<dyn EmptyRepository + '_>;

    /// A unit of work in a new transaction: its changes are kept when it is committed, and dropped otherwise.
    async fn begin(&self) -> Result<Box<dyn UnitOfWork>, DomainError>;

    /// Keeps the changes of the transaction this unit of work is in.
    async fn commit(self: Box<Self>) -> Result<(), DomainError>;
}

/// The repositories over one database, and its transactions.
pub struct SqlUnitOfWork {
    db: Db,
}

impl SqlUnitOfWork {
    /// The repositories over a connection: every write outside a transaction is committed at once.
    pub fn new(connection: DatabaseConnection) -> Self {
        Self { db: Db::Connection(connection) }
    }

    /// The repositories inside a transaction someone else opened; commit() commits it.
    pub fn in_transaction(transaction: DatabaseTransaction) -> Self {
        Self { db: Db::Transaction(transaction) }
    }
}

#[async_trait]
impl UnitOfWork for SqlUnitOfWork {
    fn things(&self) -> Box<dyn ThingRepository + '_> {
        Box::new(SqlThingRepository::new(&self.db))
    }

    fn kinds(&self) -> Box<dyn KindRepository + '_> {
        Box::new(SqlKindRepository::new(&self.db))
    }

    fn order(&self) -> Box<dyn OrderRepository + '_> {
        Box::new(SqlOrderRepository::new(&self.db))
    }

    fn entries(&self) -> Box<dyn EntryRepository + '_> {
        Box::new(SqlEntryRepository::new(&self.db))
    }

    fn empties(&self) -> Box<dyn EmptyRepository + '_> {
        Box::new(SqlEmptyRepository::new(&self.db))
    }

    async fn begin(&self) -> Result<Box<dyn UnitOfWork>, DomainError> {
        // Inside a transaction, a new one is a savepoint of it
        let transaction = match &self.db {
            Db::Connection(connection) => connection.begin().await?,
            Db::Transaction(transaction) => transaction.begin().await?,
        };
        Ok(Box::new(SqlUnitOfWork::in_transaction(transaction)))
    }

    async fn commit(self: Box<Self>) -> Result<(), DomainError> {
        if let Db::Transaction(transaction) = self.db {
            transaction.commit().await?;
        }
        Ok(())
    }
}

/// The in-memory repositories, for tests and for trying the services without a database. Memory has no
/// transactions: changes are kept as they are made, and every copy of it shares the same rows.
#[derive(Clone, Default)]
pub struct MemoryUnitOfWork {
    things: MemoryThingRepository,
    kinds: MemoryKindRepository,
    order: MemoryOrderRepository,
    entries: MemoryEntryRepository,
    empties: MemoryEmptyRepository,
}

#[async_trait]
impl UnitOfWork for MemoryUnitOfWork {
    fn things(&self) -> Box<dyn ThingRepository + '_> {
        Box::new(self.things.clone())
    }

    fn kinds(&self) -> Box<dyn KindRepository + '_> {
        Box::new(self.kinds.clone())
    }

    fn order(&self) -> Box<dyn OrderRepository + '_> {
        Box::new(self.order.clone())
    }

    fn entries(&self) -> Box<dyn EntryRepository + '_> {
        Box::new(self.entries.clone())
    }

    fn empties(&self) -> Box<dyn EmptyRepository + '_> {
        Box::new(self.empties.clone())
    }

    async fn begin(&self) -> Result<Box<dyn UnitOfWork>, DomainError> {
        Ok(Box::new(self.clone()))
    }

    async fn commit(self: Box<Self>) -> Result<(), DomainError> {
        Ok(())
    }
}

