//! The test database: the PostgreSQL database TEST_DATABASE_URL names, created from the SeaORM entities before every test.

use sea_orm::{ConnectionTrait, Database, DatabaseConnection, Schema, Statement};
use seaorm_ddl_postgresql::entities::{empty_table as empties_table, entry_table as entries_table, kind_table as kinds_table, order_table as order_table, thing_table as things_table};
use seaorm_ddl_postgresql::unit_of_work::SqlUnitOfWork;
use tokio::sync::{Mutex, MutexGuard};

/// Every test empties the same database: they take turns
static TURN: Mutex<()> = Mutex::const_new(());

/// A connection to the test database.
async fn connect() -> DatabaseConnection {
    // The entities are written for one kind of database: the tests cannot fall back to SQLite
    let url = std::env::var("TEST_DATABASE_URL").expect("The database tests need a disposable PostgreSQL database: set TEST_DATABASE_URL (it is emptied)");
    Database::connect(&url).await.expect("the test database")
}

/// The repositories over the test database, with every table dropped and created again, and the turn of the test
/// that holds it.
pub async fn open() -> (MutexGuard<'static, ()>, SqlUnitOfWork) {
    let turn = TURN.lock().await;
    let db = connect().await;
    db.execute_unprepared("DROP SCHEMA IF EXISTS \"audit\" CASCADE").await.expect("DROP SCHEMA IF EXISTS \"audit\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"empties\" CASCADE").await.expect("DROP TABLE IF EXISTS \"empties\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"audit\".\"entries\" CASCADE").await.expect("DROP TABLE IF EXISTS \"audit\".\"entries\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"Order\" CASCADE").await.expect("DROP TABLE IF EXISTS \"Order\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"kinds\" CASCADE").await.expect("DROP TABLE IF EXISTS \"kinds\" CASCADE");
    db.execute_unprepared("DROP TABLE IF EXISTS \"things\" CASCADE").await.expect("DROP TABLE IF EXISTS \"things\" CASCADE");
    db.execute_unprepared("DROP TYPE IF EXISTS \"mood\" CASCADE").await.expect("DROP TYPE IF EXISTS \"mood\" CASCADE");
    db.execute_unprepared("CREATE TYPE \"mood\" AS ENUM ('sad', 'ok', 'very happy')").await.expect("CREATE TYPE \"mood\" AS ENUM ('sad', 'ok', 'very happy')");
    db.execute_unprepared("CREATE SCHEMA \"audit\"").await.expect("CREATE SCHEMA \"audit\"");
    Schema::new(db.get_database_backend())
        .builder()
        .register(things_table::Entity)
        .register(kinds_table::Entity)
        .register(order_table::Entity)
        .register(entries_table::Entity)
        .register(empties_table::Entity)
        .apply(&db)
        .await
        .expect("the tables");
    (turn, SqlUnitOfWork::new(db))
}

#[tokio::test]
async fn is_the_one_test_database_url_names() {
    let _turn = TURN.lock().await;
    let db = connect().await;
    let row = db.query_one_raw(Statement::from_string(db.get_database_backend(), "SELECT current_database()")).await.expect("a query").expect("a row");
    let value: String = row.try_get_by_index(0).expect("a value");
    let url = std::env::var("TEST_DATABASE_URL").expect("TEST_DATABASE_URL");
    assert_eq!(url.rsplit('/').next().and_then(|name| name.split('?').next()), Some(value.as_str()));
}

