/// A valid Thing that is not stored yet; n makes its unique values differ.
pub fn new_thing(n: i32) -> Thing {
    Thing {
        token: Some(uuid::Uuid::from_u128(n as u128)),
        small: Some((n) as i16),
        num: Some(n),
        big: Some(i64::from(n)),
        price: Some(rust_decimal::Decimal::new(i64::from(n % 10000) * 100 + 50, 2)),
        r: Some((n) as f32 + 0.5),
        d: Some(f64::from(n) + 0.5),
        flag: Some(true),
        born: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date")),
        opens: Some(chrono::NaiveTime::from_hms_opt(12, (n % 60) as u32, 0).expect("a time")),
        opens_tz: Some(chrono::NaiveTime::from_hms_opt(12, (n % 60) as u32, 0).expect("a time")),
        at: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time")),
        at_tz: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date").and_hms_opt(12, 0, 0).expect("a time").and_utc().fixed_offset()),
        bin: Some(vec![n as u8]),
        data: Some(format!("{{\"n\": {n}}}")),
        plain: Some(format!("{{\"n\": {n}}}")),
        feeling: Some("sad".to_string()),
        tags: Some("{}".to_string()),
        numbers: Some("{}".to_string()),
        code: Some(format!("{:0>5}", n % 100000)),
        note: Some(format!("note-{n}")),
        ..Default::default()
    }
}

/// A stored Thing.
pub async fn add_thing(uow: &dyn UnitOfWork, n: i32) -> Thing {
    let entity = new_thing(n);
    uow.things().insert(entity).await.expect("a stored Thing")
}

/// A valid Kind that is not stored yet; n makes its unique values differ.
pub fn new_kind(n: i32) -> Kind {
    Kind {
        code: Some(format!("code-{n}")),
        day: Some(chrono::NaiveDate::from_ymd_opt(2026, 1, (n % 28 + 1) as u32).expect("a date")),
        label: Some(format!("label-{n}")),
        ..Default::default()
    }
}

/// A stored Kind.
pub async fn add_kind(uow: &dyn UnitOfWork, n: i32) -> Kind {
    let entity = new_kind(n);
    uow.kinds().insert(entity).await.expect("a stored Kind")
}

