    Entry {
        message: Some(format!("message-{n}")),
        ..Default::default()
    }
}

/// A stored Entry, with the rows it points to.
pub async fn add_entry(uow: &dyn UnitOfWork, n: i32) -> Entry {
    let parent0 = add_order(uow, n).await;
