//! The repository of the "things" table, against the test database.

use seaorm_ddl_postgresql::unit_of_work::UnitOfWork;
use super::{database, factories};

#[tokio::test]
async fn is_stored_and_read_back() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_thing(&uow, 1).await;
    let found = uow.things().find_by_id(stored.id.expect("id is set")).await.expect("a read").expect("the row");
    assert_eq!(stored.id, found.id);
}

#[tokio::test]
async fn lists_rows_by_key() {
    let (_turn, uow) = database::open().await;
    factories::add_thing(&uow, 1).await;
    factories::add_thing(&uow, 2).await;
    let page = uow.things().list(0, 1).await.expect("a page");
    assert_eq!(2, page.total);
    assert_eq!(1, page.items.len());
}

#[tokio::test]
async fn stores_the_changes() {
    let (_turn, uow) = database::open().await;
    let mut stored = factories::add_thing(&uow, 1).await;
    stored.note = Some("changed".to_string());
    uow.things().update(stored.clone()).await.expect("an update");
    let found = uow.things().find_by_id(stored.id.expect("id is set")).await.expect("a read");
    assert_eq!(Some("changed".to_string()), found.and_then(|row| row.note));
}

#[tokio::test]
async fn is_deleted() {
    let (_turn, uow) = database::open().await;
    let stored = factories::add_thing(&uow, 1).await;
    uow.things().delete(&stored).await.expect("a delete");
    assert!(uow.things().find_by_id(stored.id.expect("id is set")).await.expect("a read").is_none());
}

